llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "ZL-2201, a pyrazolopyrimidine analogue with an aniline and piperidine substituent, has a predicted absolute oral bioavailability of ~70% in humans at <15 mg, supporting high F for the similarly fused heteroaromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Tramadol, which shares the methoxyphenyl and amino-alcohol pharmacophore with the query, has a mean absolute oral bioavailability of 67.9% after a 100 mg oral dose in adult volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Rivastigmine, a basic carbamate drug, has an absolute oral bioavailability of 35% after a 3 mg oral dose versus IV, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Ranolazine, a methoxy-substituted aromatic amine with basic nitrogen, shows 35-50% oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Encainide shows a mean oral bioavailability of 42% (range 7-82%) in patients; despite wide variability, the central estimate is above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Alizapride, a methoxy-substituted benzamide with a basic pyrrolidine, has an absolute systemic availability of 72.5 ± 14.8% after oral dosing, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable analogues with measured absolute oral bioavailability in humans are above the 20% threshold (35-100%), including structurally related methoxyphenyl amino-alcohol and pyrazolopyrimidine compounds; the query is therefore predicted high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the exact query molecule.",
    "Encainide shows wide interindividual variability with some reported values below 20%, but the mean and most estimates remain above threshold.",
    "No specific data on first-pass metabolism, solubility, or permeability for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

